// ---- one validator, reader and writer for each schema ---------------------------------------------------------------------------------------------------------

/// Does the document satisfy the schema called `name` (the file name without `.schema.json`)? An unknown name is refused.
inline bool validate_message(std::string_view name, const json::Value& value) {
  for (const auto& schema : table::kSchemas) if (schema.name == name) return detail::check(schema.root, value);
  return false;
}

