/// The `ai_observation` message as a struct; false (and `out` untouched) when the document does not satisfy the schema.
inline bool parse_ai_observation(const json::Value& value, AiObservation& out) {
  if (!validate_ai_observation(value)) return false;
  AiObservation result{};
  take(value, result);
  out = std::move(result);
  return true;
}
inline std::string write_ai_observation(const AiObservation& value) {
  json::Writer w;
  put(w, value);
  return w.str();
}

