/// Reads the document as the struct of the schema called `name` and writes it back (what the nodes do with a message they receive and one they send); false when it is not valid.
inline bool rewrite_message(std::string_view name, const json::Value& value, std::string& out) {
  if (name == "ai_observation") { AiObservation message{}; if (!parse_ai_observation(value, message)) return false; out = write_ai_observation(message); return true; }
  if (name == "alarm") { Alarm message{}; if (!parse_alarm(value, message)) return false; out = write_alarm(message); return true; }
  if (name == "alarm_command") { AlarmCommand message{}; if (!parse_alarm_command(value, message)) return false; out = write_alarm_command(message); return true; }
  if (name == "alarm_policy") { AlarmPolicy message{}; if (!parse_alarm_policy(value, message)) return false; out = write_alarm_policy(message); return true; }
  if (name == "alarm_result") { AlarmResult message{}; if (!parse_alarm_result(value, message)) return false; out = write_alarm_result(message); return true; }
  if (name == "alarm_zone_feed") { AlarmZoneFeed message{}; if (!parse_alarm_zone_feed(value, message)) return false; out = write_alarm_zone_feed(message); return true; }
  if (name == "arm_profile") { ArmProfile message{}; if (!parse_arm_profile(value, message)) return false; out = write_arm_profile(message); return true; }
  if (name == "arming_modes") { ArmingModes message{}; if (!parse_arming_modes(value, message)) return false; out = write_arming_modes(message); return true; }
  if (name == "command") { Command message{}; if (!parse_command(value, message)) return false; out = write_command(message); return true; }
  if (name == "connection_client") { ConnectionClient message{}; if (!parse_connection_client(value, message)) return false; out = write_connection_client(message); return true; }
  if (name == "connection_event") { ConnectionEvent message{}; if (!parse_connection_event(value, message)) return false; out = write_connection_event(message); return true; }
  if (name == "daily_summary") { DailySummary message{}; if (!parse_daily_summary(value, message)) return false; out = write_daily_summary(message); return true; }
  if (name == "device_state") { DeviceState message{}; if (!parse_device_state(value, message)) return false; out = write_device_state(message); return true; }
  if (name == "diagnostic_token_created") { DiagnosticTokenCreated message{}; if (!parse_diagnostic_token_created(value, message)) return false; out = write_diagnostic_token_created(message); return true; }
  if (name == "diagnostic_token_info") { DiagnosticTokenInfo message{}; if (!parse_diagnostic_token_info(value, message)) return false; out = write_diagnostic_token_info(message); return true; }
  if (name == "diagnostic_token_request") { DiagnosticTokenRequest message{}; if (!parse_diagnostic_token_request(value, message)) return false; out = write_diagnostic_token_request(message); return true; }
  if (name == "electrical") { Electrical message{}; if (!parse_electrical(value, message)) return false; out = write_electrical(message); return true; }
  if (name == "electrical_command") { ElectricalCommand message{}; if (!parse_electrical_command(value, message)) return false; out = write_electrical_command(message); return true; }
  if (name == "electrical_result") { ElectricalResult message{}; if (!parse_electrical_result(value, message)) return false; out = write_electrical_result(message); return true; }
  if (name == "health") { Health message{}; if (!parse_health(value, message)) return false; out = write_health(message); return true; }
  if (name == "heatmap") { Heatmap message{}; if (!parse_heatmap(value, message)) return false; out = write_heatmap(message); return true; }
  if (name == "info") { Info message{}; if (!parse_info(value, message)) return false; out = write_info(message); return true; }
  if (name == "network") { Network message{}; if (!parse_network(value, message)) return false; out = write_network(message); return true; }
  if (name == "network_orders") { NetworkOrders message{}; if (!parse_network_orders(value, message)) return false; out = write_network_orders(message); return true; }
  if (name == "node_control_command") { NodeControlCommand message{}; if (!parse_node_control_command(value, message)) return false; out = write_node_control_command(message); return true; }
  if (name == "node_control_result") { NodeControlResult message{}; if (!parse_node_control_result(value, message)) return false; out = write_node_control_result(message); return true; }
  if (name == "node_health") { NodeHealth message{}; if (!parse_node_health(value, message)) return false; out = write_node_health(message); return true; }
  if (name == "node_maintenance") { NodeMaintenance message{}; if (!parse_node_maintenance(value, message)) return false; out = write_node_maintenance(message); return true; }
  if (name == "radar_event") { RadarEvent message{}; if (!parse_radar_event(value, message)) return false; out = write_radar_event(message); return true; }
  if (name == "server_alert") { ServerAlert message{}; if (!parse_server_alert(value, message)) return false; out = write_server_alert(message); return true; }
  if (name == "solar_battery") { SolarBattery message{}; if (!parse_solar_battery(value, message)) return false; out = write_solar_battery(message); return true; }
  if (name == "solar_battery_command") { SolarBatteryCommand message{}; if (!parse_solar_battery_command(value, message)) return false; out = write_solar_battery_command(message); return true; }
  if (name == "solar_battery_result") { SolarBatteryResult message{}; if (!parse_solar_battery_result(value, message)) return false; out = write_solar_battery_result(message); return true; }
  if (name == "solar_inverter") { SolarInverter message{}; if (!parse_solar_inverter(value, message)) return false; out = write_solar_inverter(message); return true; }
  if (name == "system_event") { SystemEvent message{}; if (!parse_system_event(value, message)) return false; out = write_system_event(message); return true; }
  if (name == "telemetry") { Telemetry message{}; if (!parse_telemetry(value, message)) return false; out = write_telemetry(message); return true; }
  if (name == "voice_turn_meta") { VoiceTurnMeta message{}; if (!parse_voice_turn_meta(value, message)) return false; out = write_voice_turn_meta(message); return true; }
  if (name == "voice_turn_result") { VoiceTurnResult message{}; if (!parse_voice_turn_result(value, message)) return false; out = write_voice_turn_result(message); return true; }
  return false;
}

